// Category B — a picture of a message the store will send through another channel, shown beside the
// form that composes it, wherever an owner sets up a customer message: the booking reminders, the
// coupon step, the deposit notice (「알림톡 도착」).
//
// It is a picture, not the message: nothing in it is pressable. It is a named region on ScrollArea, so
// a screen reader hears where the preview starts and ends, and a long template scrolls with a tab stop
// only while it actually overflows. The rule under the sender is drawn, not announced.
//
// The channel's own colour (`channelColor`) is the caller's, because the channel is not Sando's brand:
// Sando ships no third-party colour. A channel's colour does not follow the theme, so its label ink
// comes with it (`channelForeground`), and the caller owns that pair's 4.5:1. Without them the band is
// the neutral fill under the default ink.
//
// The message text keeps its line breaks, as a template's do.
//
// ponytail: buttons inside the message (a 「예약 확인하기」 link) are not drawn; add them when a template
// has one.
import type { CSSProperties, ReactNode, Ref } from "react";
import { ScrollArea } from "./ScrollArea";
import { Separator } from "./Separator";
import "./MessagePreview.css";

export interface MessagePreviewBaseProps {
  /** The channel band's label, e.g. "알림톡 도착". */
  channelLabel: string;
  /** A picture heading a templated message, e.g. a calendar icon. Decorative. */
  heroMedia?: ReactNode;
  /** The title under the picture, e.g. "예약 하루 전". */
  heroTitle?: ReactNode;
  /** Who sends it, e.g. the store's name. */
  sender: ReactNode;
  /** The message text. Line breaks are kept. */
  children: ReactNode;
  /** A closing line in the supporting ink, e.g. "내일 만나요!". */
  note?: ReactNode;
}

export type MessagePreviewProps = MessagePreviewBaseProps &
  (
    | {
        /** The channel's colour for the band, as a CSS colour; the same in every theme. */
        channelColor: string;
        /** The band label's ink on `channelColor`, clearing 4.5:1 against it. */
        channelForeground: string;
      }
    | { channelColor?: undefined; channelForeground?: undefined }
  ) & {
    /** Accessible name of the preview, e.g. "알림톡 미리보기". */
    "aria-label": string;
    /** Additional class (optional). sd-message-preview is always preserved. */
    className?: string;
    /** Forwarded to the root element. */
    ref?: Ref<HTMLDivElement>;
  };

export function MessagePreview({
  channelLabel,
  heroMedia,
  heroTitle,
  sender,
  children,
  note,
  channelColor,
  channelForeground,
  "aria-label": ariaLabel,
  className,
  ref,
}: MessagePreviewProps) {
  const style = channelColor ? ({ "--sd-message-preview-channel": channelColor, "--sd-message-preview-channel-foreground": channelForeground } as CSSProperties) : undefined;
  return (
    <ScrollArea
      ref={ref}
      role="region"
      aria-label={ariaLabel}
      className={className ? `sd-message-preview ${className}` : "sd-message-preview"}
    >
      <div className="sd-message-preview__header sd-type-label-medium-emphasized" data-channel={channelColor ? true : undefined} style={style}>
        {channelLabel}
      </div>
      {(heroMedia != null || heroTitle != null) && (
        <div className="sd-message-preview__hero">
          {heroMedia != null && <span aria-hidden="true">{heroMedia}</span>}
          {heroTitle != null && <span className="sd-type-title-medium-emphasized">{heroTitle}</span>}
        </div>
      )}
      <div className="sd-message-preview__body">
        <span className="sd-message-preview__sender sd-type-body-medium-emphasized">{sender}</span>
        <Separator aria-hidden="true" />
        <div className="sd-message-preview__text sd-type-body-medium">{children}</div>
        {note != null && <div className="sd-message-preview__note sd-type-body-medium">{note}</div>}
      </div>
    </ScrollArea>
  );
}

/* A bubble: the channel band, an optional hero band, then the sender, a rule and the message. The
   bubble fills its parent's width and scrolls inside the height its parent gives it. */
.sd-message-preview {
  display: flex;
  flex-direction: column;
  min-block-size: 0;
  border: var(--sd-message-preview-border-width) solid var(--sd-message-preview-border);
  border-radius: var(--sd-message-preview-radius);
  corner-shape: superellipse(var(--sd-radius-curve));
  background: var(--sd-message-preview-background);
  color: var(--sd-message-preview-foreground);
  /* The bubble is a ScrollArea that paints its own surface, so it opts out of the scrollport's
     compensated gutter: the negative margin would grow the painted bubble past its slot. */
  margin: 0;
  padding: 0;
}

.sd-message-preview__header {
  padding: var(--sd-message-preview-header-padding) var(--sd-message-preview-padding);
  background: var(--sd-message-preview-header-background);
}
.sd-message-preview__header[data-channel] {
  background: var(--sd-message-preview-channel);
  color: var(--sd-message-preview-channel-foreground);
}

.sd-message-preview__hero {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: var(--sd-message-preview-gap);
  padding: var(--sd-message-preview-hero-padding);
  background: var(--sd-message-preview-hero-background);
  text-align: center;
}

.sd-message-preview__body {
  display: flex;
  flex-direction: column;
  gap: var(--sd-message-preview-gap);
  padding: var(--sd-message-preview-padding);
}

/* The sender, the message and the note are text the bubble draws on its own painted surface, so they
   take the text inset (component-contract.md §6 rule 8, component-owned text); the rule between them
   stays on the body's line. Inline only. */
.sd-message-preview__sender,
.sd-message-preview__text,
.sd-message-preview__note {
  padding-inline: var(--sd-message-preview-text-padding-inline);
}

.sd-message-preview__text {
  margin: 0;
  white-space: pre-line;
  overflow-wrap: anywhere;
}

.sd-message-preview__note {
  margin: 0;
  white-space: pre-line;
  overflow-wrap: anywhere;
  color: var(--sd-message-preview-note-foreground);
}
